MAP
  NAME "webatlas"
  STATUS ON
  EXTENT 101 8 110 23.5
  UNITS DD
  IMAGECOLOR 255 255 255
  SHAPEPATH "/data"
  FONTSET "/etc/mapserver/fonts.txt"

  SYMBOL
    NAME "circle"
    TYPE ELLIPSE
    FILLED TRUE
    POINTS
      1 1
    END
  END

  WEB
    METADATA
      "wms_title" "WebAtlas GIS Server"
      "wms_onlineresource" "http://localhost:8081/?"
      "wms_enable_request" "*"
      "wms_srs" "EPSG:4326 EPSG:3857"
      "wfs_enable_request" "*"
      "wfs_title" "WebAtlas WFS Server"
      "wfs_srs" "EPSG:4326 EPSG:3857"
    END
  END

  PROJECTION
    "init=epsg:4326"
  END

  # -----------------------------------------------------------
  # LAYER 1: Ranh giới Tỉnh (diaphantinh)
  # -----------------------------------------------------------
  LAYER
    NAME "diaphantinh"
    TYPE POLYGON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=gis user=postgres password=postgres port=5432"
    DATA "geom FROM bien_gioi_tinh USING UNIQUE fid USING SRID=4326"
    STATUS ON
    TOLERANCE 10
    TOLERANCEUNITS pixels
    PROJECTION
      "init=epsg:4326"
    END
    METADATA
      "wms_title" "Ranh giới Tỉnh"
      "wms_name" "diaphantinh"
      "wms_srs" "EPSG:4326 EPSG:3857"
      "wfs_enable_request" "*"
      "gml_include_items" "all"
      "wms_include_items" "all"
    END
    TEMPLATE "dummy"
    CLASS
      NAME "Province"
      STYLE
        OUTLINECOLOR 75 85 99
        WIDTH 1.5
      END
    END
  END

  # -----------------------------------------------------------
  # LAYER 1B: Nhãn Tỉnh ở Trung tâm (diaphantinh_label)
  # -----------------------------------------------------------
  LAYER
    NAME "diaphantinh_label"
    TYPE POINT
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=gis user=postgres password=postgres port=5432"
    DATA "center_geom FROM (SELECT fid, adm1_name1, ST_PointOnSurface(geom) AS center_geom FROM bien_gioi_tinh) AS subquery USING UNIQUE fid USING SRID=4326"
    STATUS ON
    LABELITEM "adm1_name1"
    PROCESSING "LABEL_NO_CLIP=ON"
    PROJECTION
      "init=epsg:4326"
    END
    METADATA
      "wms_title" "Nhãn Ranh giới Tỉnh"
      "wms_name" "diaphantinh_label"
      "wms_srs" "EPSG:4326 EPSG:3857"
    END
    CLASS
      NAME "Province Label"
      LABEL
        TYPE TRUETYPE
        FONT "sans-bold"
        SIZE 10.5
        COLOR 30 41 59
        OUTLINECOLOR 255 255 255
        OUTLINEWIDTH 2.5
        POSITION CC
        FORCE TRUE
        ENCODING "UTF-8"
      END
    END
  END

  # -----------------------------------------------------------
  # LAYER 2: Ranh giới Quốc gia (gadm41_vnm_3)
  # -----------------------------------------------------------
  LAYER
    NAME "gadm41_vnm_3"
