    METADATA
      "wms_title" "Ranh giới Quốc gia"
      "wms_name" "gadm41_vnm_3"
      "wms_srs" "EPSG:4326 EPSG:3857"
      "wfs_enable_request" "*"
      "gml_include_items" "all"
      "wms_include_items" "all"
    END
    TEMPLATE "dummy"
    CLASS
      STYLE
        OUTLINECOLOR 160 160 160
        WIDTH 0.8
      END
    END
  END

  # -----------------------------------------------------------
