      "wms_srs" "EPSG:4326 EPSG:3857"
      "wfs_enable_request" "*"
      "gml_include_items" "all"
      "wms_include_items" "all"
    END
    TEMPLATE "dummy"
    CLASS
      STYLE
        COLOR 14 165 233
        WIDTH 2.0
      END
    END
  END

