  # -----------------------------------------------------------
  # LAYER 10: RASTER DEM (dem)
  # -----------------------------------------------------------
  LAYER
    NAME "dem"
    TYPE RASTER
    DATA "/data/processed/raster/06_DEM.tif"
    STATUS ON
    PROJECTION
      "init=epsg:4326"
    END
    METADATA
      "wms_title" "Mô hình số độ cao DEM"
      "wms_name" "dem"
      "wms_srs" "EPSG:4326 EPSG:3857"
    END
  END

